# catalog.py의 add와 ARTICLES를 공유하는 생성기 네임스페이스에서 실행한다.

add(11,'학교평가계획읽기','학교 평가 계획 읽기, 기말고사와 수행평가 준비를 함께 나누기','시험·평가','중등·고등·학부모',
'학교 평가 계획에서 반영 항목과 기준을 확인하고, 지필평가·수행평가의 준비 일정을 함께 정합니다.',[
('학교 이름보다 과목의 현재 평가 안내를 보세요','“내신 비중이 높은 학교”라는 표현만으로 평가 방식을 알 수 없습니다. 해당 학년·학기·과목의 평가 계획에서 지필·수행평가 항목과 반영 비율, 일정, 기준을 확인하세요. 이전 학년도 안내를 그대로 적용하지 않고 현재 자료인지 살핍니다. 수업 태도나 과제 제출이 어떻게 반영되는지도 실제 기준에서 확인해야 하며, 불분명한 내용은 교과 선생님께 질문합니다.'),
('반영 비율과 오늘의 우선순위를 함께 살피세요','비율이 큰 항목에만 시간을 쓰면 제출이 임박한 과제나 필수 준비를 놓칠 수 있습니다. 마감·현재 완성도·필요한 도움을 함께 보고 할 일을 고르세요. 수행평가는 조사·초안·수정·제출로 나누어 배치합니다. 점수 계산이 필요하면 학교의 산출 방식을 확인하고 예시 비율을 실제 성적 공식으로 사용하지 않습니다.'),
('수업 자료와 기준표를 작업 목록으로 바꾸세요','지필 범위에서는 아직 설명하지 못하는 개념을 찾고, 수행평가 기준표에서는 답안과 결과물에 필요한 요소를 찾습니다. 영어·수학의 이전 개념이 필요하면 현재 과제에 직접 연결되는 부분을 보완하세요. 국어는 주장과 지문 근거가 연결되는지 확인합니다. 기출 자료를 사용한다면 출처와 공개·이용 가능 여부도 살핍니다.'),
('변경 공지와 제출 확인까지 포함하세요','일정·제출 방식·파일 형식·준비물이 바뀌었는지 확인합니다. 학생은 완료한 작업과 질문을 나누고 부모는 마감과 이동 일정을 지원할 수 있습니다. 채점에 궁금한 점이 있으면 학교의 안내된 절차로 질문하세요. 학원의 일반 조언도 해당 학교 기준에 맞춰 조정해야 하며 모든 학교에 같은 비율과 요구를 적용하지 않습니다.')],
'과학 보고서와 지필평가가 같은 주에 있다면 주초에 보고서 초안을 작성하고 중간에 근거·단위·출처를 확인합니다. 나머지 시간은 지필 범위 중 설명하지 못한 개념에 배치하되 제출 확인 시간을 남깁니다.',
['현재 평가 안내를 찾았다.','반영 항목과 기준을 확인했다.','작업 단계를 나눴다.','수업 자료와 연습을 연결했다.','변경 공지와 제출을 확인했다.'],
[['비율이 높은 항목만 준비하면 되나요?','비율뿐 아니라 마감·완성도·필수 준비를 함께 봐야 합니다. 학교 기준에 맞는 작업을 빠뜨리지 않도록 항목별로 확인하세요.'],['평가 계획은 어디서 보나요?','학교 홈페이지·가정통신문·교과별 안내를 확인하세요. 찾기 어렵거나 해석이 불분명한 항목은 담임·교과 선생님께 질문할 수 있습니다.']],['school'],'수행평가준비')

add(12,'학년변화어려움관찰','학년이 바뀐 뒤 성적이 흔들릴 때, 달라진 요구를 찾아보기','학부모·상담','초등·중등·고등·학부모',
'학년 변화 뒤의 어려움을 과제량·기초·답안 요구·생활 일정으로 나누어 관찰하고 지원 범위를 정합니다.',[
('점수 하락을 학생의 특징으로 고정하지 마세요','학년이 바뀌면 교과·과제·평가 조건이 달라질 수 있습니다. 점수만 비교해 성실성이나 능력을 단정하기보다 최근 과제의 어떤 요구가 달라졌는지 확인하세요. 문제 길이·필요한 설명·과목 수·마감을 살핍니다. “지금은 어느 단계가 어렵니?”라고 물어 학생의 경험과 부모의 관찰을 함께 모으세요.'),
('과제량 증가와 기초의 빈틈을 구분하세요','시간 안에 끝내지 못하는 이유가 분량인지 문제 하나에서 오래 막히는 것인지 살핍니다. 대표 과제로 현재 필요한 이전 개념을 확인하세요. 영어는 문장 구조와 어휘, 수학은 계산과 식의 의미, 국어는 근거 읽기와 요약을 볼 수 있습니다. 모든 이전 단원을 다시 하기보다 현재 과제의 연결 개념부터 보완합니다.'),
('답안에 필요한 설명이 달라졌는지 보세요','정답 외에 이유와 근거가 필요한 활동일 수 있습니다. 학교 예시와 기준을 보고 학생 답안에서 빠진 요소를 찾아보세요. 개념을 아는 것과 글로 표현하는 것을 나눠 연습합니다. “꼼꼼히 하라”는 말보다 어떤 조건·과정·근거를 적어야 하는지 구체적으로 확인하면 다음 과제에 적용하기 쉽습니다.'),
('지원은 관찰한 어려움 하나부터 조정하세요','시간이 부족하면 과제량과 이동 일정을, 개념이 불확실하면 설명과 확인 활동을 조정합니다. 생활·관계의 어려움도 말할 시간을 두세요. 적응이 늦다는 이유로 비교하거나 처벌하지 않습니다. 불안·피로가 학교생활에 계속 영향을 주면 보호자와 학교에 알려 도움을 구합니다. 점수와 독립 수행을 함께 확인하세요.')],
'예전에는 숙제를 빨리 끝냈는데 지금은 첫 문항에서 오래 멈춘다면 시간을 먼저 늘리지 않습니다. 풀이를 보고 필요한 이전 개념 하나를 찾아 설명과 대표 문제 확인을 요청합니다. 이후 같은 단계의 어려움이 줄었는지 기록합니다.',
['과제 요구의 변화를 비교했다.','분량과 개념을 나눴다.','답안에서 빠진 요소를 찾았다.','생활·관계 이야기를 들었다.','지원할 한 단계를 정했다.'],
[['성적 하락은 선행 부족 때문인가요?','한 원인으로 단정하기 어렵습니다. 현재 필요한 기초·답안 요구·시간·생활 변화를 함께 확인하세요.'],['이전 학년을 전부 복습해야 하나요?','현재 과제에 필요한 연결 개념부터 확인할 수 있습니다. 빈틈을 보완하고 다시 적용한 뒤 범위를 조정하세요.']],['feedback','stress'],'수학기초점검')

add(13,'시험후공부방법한가지실험','시험 뒤 공부 방법 바꾸기, 한 가지 변화만 비교해 보기','계획·습관','중등·고등',
'시험 준비 기록에서 바꿀 활동 하나를 고르고, 비교할 과제와 확인 날짜를 정해 학습 방법을 점검합니다.',[
('결과와 준비 기록을 함께 모으세요','사용한 자료·공부 시기·질문 해결 방법을 짧게 남깁니다. 잘된 과목과 아쉬운 과목을 모두 보되 결과만으로 방법의 효과를 확정하지 않습니다. 범위·난도·문항 요구가 달랐을 수 있기 때문입니다. 플래너와 실제 풀이를 함께 보고 회복이 필요하면 점검 시점을 조정합니다. 시험 직후가 모든 학생에게 유일한 최적 시점인 것은 아닙니다.'),
('직접 실행할 행동 하나를 고르세요','“더 열심히” 대신 “복습 뒤 해설 없이 대표 문제 다시 풀기”처럼 씁니다. 교재·시간·수업·복습을 한꺼번에 바꾸면 무엇이 도움이 됐는지 살피기 어렵습니다. 기록에서 필요한 한 가지를 고르고 시작하기 쉬운 분량을 정하세요. 유지할 행동도 남겨 모든 준비가 잘못됐다는 느낌 없이 다음 시도를 준비합니다.'),
('비슷한 요구의 과제로 비교하세요','같은 개념과 비슷한 요구의 과제에서 소요 시간·혼자 해결한 단계·도움받은 부분·남은 오류를 기록합니다. 답을 기억했을 수 있어 조건이 바뀐 문항도 확인할 수 있습니다. 이 개인 점검 결과를 모든 학생에게 통하는 효과나 다음 시험 점수 보장으로 확대하지 않습니다. 실제 실행 여부와 수행 변화를 따로 기록하세요.'),
('확인일에는 유지·수정·도움 요청을 정하세요','실행하지 못했다면 분량·시점·자료를 수정합니다. 실행해도 같은 단계에서 막히면 설명과 피드백을 요청하세요. 도움이 됐다면 다음 범위에도 적용해 보되 과제가 달라져도 맞는지 점검합니다. 학생이 자신의 변화와 다음 행동을 설명하도록 하며 작은 기간의 점수만으로 방법을 성공·실패로 나누지 않습니다.')],
'영어 복습을 읽기만 했다면 “문장 두 개를 책 없이 설명하기”를 한 주 시도할 수 있습니다. 시작 전과 확인일에 비슷한 문장의 독립 설명을 기록합니다. 부담이 크면 문장을 줄이고 막힌 구조는 수업 질문으로 남깁니다.',
['결과와 기록을 모았다.','변화 하나를 정했다.','비교 과제의 요구를 맞췄다.','실행과 수행을 나눴다.','확인일의 선택을 정했다.'],
[['공부법을 전부 바꾸면 안 되나요?','필요한 변화는 할 수 있지만 한꺼번에 바꾸면 원인을 살피기 어렵습니다. 중요한 행동 하나부터 비교하고 범위를 넓혀 보세요.'],['일주일 뒤 점수가 안 오르면 효과가 없나요?','짧은 기간에는 실행과 독립 수행을 먼저 볼 수 있습니다. 서로 다른 시험의 점수만으로 방법의 효과를 확정하지 않습니다.']],['meta'],'시험후분석')

add(14,'학습프로그램상담비교표','학습 프로그램 비교표, 설명보다 학생이 할 활동을 적기','학부모·상담','학부모·중등·고등',
'학습 프로그램 상담 내용을 같은 항목으로 기록해 학생 활동·피드백·과제와 실제 운영 조건을 비교합니다.',[
('이름 옆에 실제 수업 활동을 적으세요','진단·맞춤·코칭이라는 이름만으로 내용을 알기 어렵습니다. 설명을 듣는 시간, 학생의 풀이, 질문 방식, 수업 뒤 확인 과제를 묻습니다. 어느 형식이 항상 우수하다고 전제하지 말고 현재 필요한 도움을 받을 수 있는지 보세요. 확인한 답변과 미확인 내용을 나눠야 광고 문구를 모은 표에서 실제 비교 자료로 바뀝니다.'),
('수준 조정에 어떤 자료를 쓰는지 확인하세요','검사 이름보다 최근 과제와 독립 수행을 어떻게 확인하는지 묻습니다. 교재·진도·보충 범위의 기준과 조정 시점을 함께 보세요. 학습 유형 하나로 모든 활동을 제한하지 않고 과제의 필요와 비교합니다. 학생이 혼자 할 부분과 도움받을 부분이 어떻게 다른지 같은 대표 문항이나 질문으로 확인할 수 있습니다.'),
('피드백 뒤 학생 행동을 비교 항목에 넣으세요','질문을 받는다는 안내에 더해 설명 후 다시 풀거나 수정할 기회가 있는지 묻습니다. 확인 결과가 다음 수업에 어떻게 반영되는지, 반복 오류에 어떤 도움을 받는지 기록하세요. 상담 시간이 많다는 사실만으로 효과를 단정하지 않습니다. 조언을 과제에 적용하고 다시 확인하는 흐름이 있는지 살핍니다.'),
('운영 조건과 학생 의견도 함께 기록하세요','실제 수업일·시간·대상·교재·비용·변경 조건은 지점에 확인하고 문서를 보관합니다. 이동과 학교 과제에 미치는 영향도 비교하세요. 표에 확인 날짜와 추가 질문을 남기고 공개되지 않은 조건을 추측하지 않습니다. 최근 숙제로 어떤 도움이 필요한지 확인한 뒤 학생의 의견을 함께 반영해 선택합니다.')],
'두 프로그램에 “대표 문제 설명 → 혼자 재풀이 → 남은 질문 확인”이 어떻게 이어지는지 각각 묻습니다. 답변을 최근 숙제의 어려움과 비교하고 시간·비용·이동 조건까지 같은 표에 적어 볼 수 있습니다.',
['이름과 활동을 나눴다.','수준 조정 자료를 물었다.','피드백 이후를 확인했다.','운영 조건을 기록했다.','학생 의견을 들었다.'],
[['소수정예라는 이름만으로 맞춤 지도를 알 수 있나요?','학생 수와 함께 수준 조정·질문·독립 수행 확인이 실제로 어떻게 이루어지는지 확인하세요.'],['유형 검사가 있으면 더 좋은가요?','검사 이름보다 활용과 실제 과제 확인 방법을 보세요. 유형으로 활동을 제한하거나 효과를 보장하는 설명은 근거를 확인해야 합니다.']],['styles','feedback'],'학원수업비교')

add(15,'학부모설명회질문과적용','학부모 설명회·세미나 활용하기, 질문과 가정의 한 가지 변화 남기기','학부모·상담','학부모',
'학부모 설명회 전에 질문과 최근 자료를 준비하고, 들은 정보를 확인해 가정에서 시도할 행동으로 옮깁니다.',[
('해결할 질문을 하나로 좁혀 보세요','최근 반복된 어려움 하나를 정하고 학생의 생각을 먼저 듣습니다. 과제 시작·질문 준비·학교 안내 중 무엇이 어려운지 최근 자료로 확인하세요. 공개적인 자리에서는 개인정보가 담긴 자료를 불필요하게 보여주지 않습니다. 질문은 “공부를 잘하게 하려면?”보다 현재 상황과 해본 행동을 함께 적어 준비합니다.'),
('일반 조언과 학교별 정보를 구분하세요','학습 조언은 참고하되 평가·진로 정보는 현재 공식 안내와 비교합니다. 발표 자료의 날짜·출처·적용 학년을 확인하세요. 한 학습 유형에 공부법을 고정하기보다 실제 과제의 이해를 살피는 방법을 묻습니다. 모든 학생에게 같은 선행 범위와 분량을 권하는 설명은 자녀의 현재 필요와 다시 비교합니다.'),
('집에서 할 일과 부모의 지원을 나누세요','“막힌 줄을 표시한 뒤 무엇을 확인하면 좋을까요?”처럼 시도한 활동 다음을 질문합니다. 답변을 학생의 실행과 부모의 지원으로 나눠 적고, 자녀와 상의해 한 가지 활동을 선택하세요. 내용 전체를 한꺼번에 적용하지 않습니다. 생활 일정 안에서 실행할 시점과 확인할 자료를 정합니다.'),
('참석 뒤 확인과 후속 질문을 남기세요','참석 자체를 학습 변화로 판단하지 않습니다. 시도한 활동의 어려움과 수행 자료를 다음 상담에 가져갈 수 있습니다. 실제 개최 여부·대상·일정·비용은 지점별 안내에서 확인하세요. 모든 지점이 정기 무료 행사를 운영한다고 가정하지 않습니다. 가정의 지원도 학생의 경험에 맞춰 조정합니다.')],
'숙제 완료 뒤 배운 내용을 설명하기 어렵다면 “완료 뒤 확인할 질문”을 준비합니다. 설명회 후 학생과 과제 하나를 골라 핵심을 짧게 설명해 보고, 여전히 막힌 부분을 후속 상담 질문으로 남깁니다.',
['자녀 생각을 들었다.','질문 하나를 준비했다.','날짜·출처를 확인했다.','시도할 행동을 함께 골랐다.','행사 조건을 확인했다.'],
[['들은 내용을 전부 적용해야 하나요?','현재 과제와 생활에 필요한 활동 하나부터 선택하세요. 자녀의 학교·학년·상황에 맞는지 확인하고 결과로 조정할 수 있습니다.'],['모든 지점에서 무료 세미나를 하나요?','해당 지점의 현재 개최 여부·대상·비용·일정을 확인해야 합니다. 이 글은 참석과 정보 활용 방법을 설명합니다.']],['parents','styles'],'학부모상담준비')

add(16,'개학후슬럼프시작조정','개학 뒤 공부가 버거울 때, 첫 과제와 도움 요청을 작게 정하기','마음·컨디션','중등·고등·학부모',
'개학 뒤 생활과 과제의 부담을 나누어 살피고, 작은 시작 활동과 도움을 요청할 사람을 정합니다.',[
('의욕 저하를 한 원인으로 설명하지 마세요','생활 일정·과제·관계·피로 등 여러 조건을 함께 살핍니다. 언제 시작이 어렵고 어떤 과제에서 멈추는지 학생의 말을 듣습니다. 부모의 관찰과 다르면 확인할 질문을 정하세요. “개학 슬럼프”는 일상의 어려움을 설명하는 말이며 진단이 아닙니다. 공부량만 늘리기보다 생활과 학습 부담을 나눠 봅니다.'),
('생활 복귀와 오늘 과제를 따로 정하세요','학교 일정에 맞춰 취침·기상·식사와 준비를 함께 봅니다. 오늘 공부는 교재를 꺼내 남은 질문 하나를 찾는 활동부터 시작할 수 있습니다. 이전보다 많은 양을 계획하기보다 실제 시간과 어려움을 기록하세요. 시작하지 못한 날에도 방해 조건을 남겨 다음 분량과 시점을 바꿔 봅니다.'),
('혼자 시도할 범위와 질문 시점을 정하세요','이해하지 못한 채 오래 버티는 것과 필요한 연습을 구분합니다. 해본 흔적과 막힌 줄을 남기고 담임·교과 선생님·보호자 등 누구에게 질문할지 정하세요. 친구와 공유하는 계획이 비교 부담을 만든다면 방식을 조정합니다. 도움 요청도 학습의 한 단계로 볼 수 있습니다.'),
('생활의 어려움이 계속되면 지원을 구하세요','불안·피로가 이어져 잠·식사·등교에 영향을 준다면 보호자와 학교에 알리고 적절한 상담·의료 도움을 구할 수 있습니다. 작은 목표나 긍정 문구로 모든 어려움이 해결된다고 말하지 않습니다. 결과를 추궁하기보다 부담과 필요한 지원을 확인하고 회복 상태에 맞춰 계획을 조정합니다.')],
'수학 과제 시작이 어렵다면 교재에서 모르는 개념 하나를 표시합니다. 다음 수업에서 질문하고 설명 뒤 대표 문제를 확인합니다. 실행이 어려우면 생활과 분량을 수정하고 일상의 어려움이 계속되면 보호자와 학교에 알립니다.',
['생활과 과제 부담을 나눴다.','작은 시작을 정했다.','막힌 질문을 남겼다.','도움받을 사람을 확인했다.','일상 영향을 살폈다.'],
[['의욕이 없으면 공부량을 늘려야 하나요?','현재 생활과 과제 부담을 먼저 보세요. 작은 활동의 실제 수행을 보며 분량과 지원을 조정할 수 있습니다.'],['작은 목표로도 계속 힘들면요?','보호자와 학교에 알려 주세요. 불안·피로가 일상에 계속 영향을 주면 적절한 상담·의료 도움을 구할 수 있습니다.']],['stress'],'공부미루기')

add(17,'성취도자료모아보기','학습 성취도 확인하기, 점수·풀이·설명을 한 묶음으로 보기','시험·평가','초등·중등·고등·학부모',
'시험 점수와 실제 풀이·설명 자료를 함께 모아 현재 성취와 다음 과제를 확인하는 방법을 정리합니다.',[
('확인할 학습 목표부터 정하세요','개념 이해·적용·근거 설명 중 무엇을 확인할지 정합니다. 가정의 점검과 학교의 공식 평가는 역할이 다르므로 개인 점검을 공식 성취도나 등급으로 부르지 않습니다. 목표가 분명해야 어떤 자료를 모으고 다음 과제를 어떻게 정할지 판단할 수 있습니다. 확인 범위는 최근 단원처럼 작게 시작하세요.'),
('수치에는 과제 조건을 함께 적으세요','정답 수·소요 시간·완료량과 함께 범위·난도·도움 여부를 남깁니다. 다른 문제 묶음의 정답률은 같은 의미가 아닐 수 있습니다. 전체 문항 수와 오류의 개념·요구를 확인하세요. 프로젝트도 수치로 평가될 수 있어 시험은 정량, 과제는 정성이라는 식으로 이름만 보고 나누지 않습니다.'),
('과정은 보이는 행동으로 기록하세요','풀이·수정 전후 답안·학생 설명을 모읍니다. “태도가 좋다”보다 “근거를 찾아 선택 이유를 설명했다”처럼 씁니다. 자기평가·동료 의견도 실제 자료와 비교하세요. 대표 자료 몇 장으로 시작하고 수집이 학습보다 큰 과제가 되지 않도록 범위를 좁힙니다. 잘된 행동과 남은 질문을 함께 남깁니다.'),
('자료의 판단을 다음 행동으로 연결하세요','정답은 맞지만 근거가 불확실하면 설명을 확인하고, 설명은 가능하지만 오래 걸리면 실행 과정을 살핍니다. 보완 하나를 정해 비슷한 과제로 다시 확인하세요. 가정 기록은 상담에 사용할 수 있지만 장기 능력·진학 결과를 단정하는 자료가 아닙니다. 다음 확인에서도 조건과 도움 여부를 기록합니다.')],
'과학 문제는 맞혔지만 이유를 설명하지 못했다면 정답과 근거 미확인을 함께 적습니다. 실험 조건을 다시 보고 자기 말로 설명한 뒤 다른 사례에서도 같은 개념을 사용할 수 있는지 확인합니다.',
['학습 목표를 정했다.','문항 수·도움을 기록했다.','풀이·설명을 모았다.','관찰을 행동으로 적었다.','보완 하나를 정했다.'],
[['정답률만으로 이해를 알 수 있나요?','문항 조건·도움·풀이 근거를 함께 봐야 합니다. 답을 기억했거나 우연히 맞혔을 수 있으므로 설명과 다른 조건 적용도 확인하세요.'],['가정 점검이 공식 성취도인가요?','학습·상담 자료이며 공식 평가를 대체하지 않습니다. 성취도 산출은 해당 학교 안내를 따릅니다.']],['feedback'],'학습변화기록')

add(18,'주말점검과완충시간','주말 학습 점검, 밀린 숙제와 이해 확인을 따로 배치하기','계획·습관','중등·고등·학부모',
'주말에 한 주의 과제와 이해를 따로 확인하고, 다음 주 보완과 휴식을 위한 시간을 남깁니다.',[
('점검일은 실제 일정에 맞춰 정하세요','토요일이 편하면 토요일, 다른 날이 맞으면 그날에 짧은 점검을 둡니다. 특정 요일의 효과를 보장하지 않습니다. 플래너·과제에서 완료·질문·다음 마감을 확인하세요. 점검이 밀린 숙제 전부를 처리하는 시간이 되지 않도록 목적을 나눕니다. 학생이 먼저 기록을 설명하고 부모는 실행 조건을 확인합니다.'),
('완료율과 이해를 따로 확인하세요','완료율은 실행 자료이며 이해나 점수 향상을 뜻하지 않습니다. 대표 질문과 문제를 자료 없이 해보고 설명을 확인하세요. 완료율을 적는다면 계획 항목의 크기도 살핍니다. 큰 과제 하나와 짧은 과제 여러 개를 체크 수만으로 비교하면 부담을 놓칠 수 있습니다. 필요한 경우 실제 작업 단계로 나눕니다.'),
('미완료 이유를 다음 조정에 사용하세요','시간 부족·난도·자료 누락을 나눕니다. 질문할 시점과 필요한 자료를 정하고 큰 과제는 단계로 나누세요. 미완료를 다음 주에 전부 더하지 않고 새 마감과 생활 일정도 반영합니다. 한 주의 실패라는 평가보다 수정할 조건을 남기며 학생이 필요한 지원을 말할 수 있도록 합니다.'),
('보충과 휴식의 여유를 남기세요','주말의 모든 시간을 채우면 예상하지 못한 과제와 휴식에 대응하기 어렵습니다. 실제 가능한 비어 있는 시간을 정하고 다음 주 첫 활동과 준비 자료만 확인한 뒤 마무리하세요. 점검이 길어져 갈등이 생기면 항목을 줄이고 대화 방식을 바꿉니다. 일정 예시를 의무적인 생활 규칙으로 적용하지 않습니다.')],
'남은 영어 과제에서 단어는 혼자 확인하고 독해는 한 문장에서 막혔다면, 단어 확인과 질문 준비를 따로 배치합니다. 다음 주에 같은 분량을 더하기보다 독해 질문을 해결할 시간을 남길 수 있습니다.',
['점검일을 정했다.','완료와 이해를 나눴다.','미완료 이유를 적었다.','새 일정을 반영했다.','휴식·보충 여유를 남겼다.'],
[['토요일에 꼭 해야 하나요?','꾸준히 돌아볼 수 있는 날을 고르면 됩니다. 요일보다 기록을 다음 계획에 반영하는 과정이 필요합니다.'],['완료율이 낮으면 과제를 더 해야 하나요?','이유와 과제 크기를 먼저 보세요. 분량을 나누거나 질문 시간을 추가하는 등 원인에 맞춰 조정합니다.']],['meta'],'학습플래너')

add(19,'개학전과제표본점검','개학 전 공부 점검, 전 범위 시험 대신 최근 과제부터 살펴보기','학기·방학','초등·중등·학부모',
'개학 전에 최근 과제의 작은 표본과 생활 일정을 살펴 필요한 보완·자료·질문을 준비합니다.',[
('방학 실적보다 현재 출발점을 보세요','개학 안내·준비물·과제 마감을 확인하고 최근 익숙한 과제를 고릅니다. 한 번에 전체 학습 상태를 알아냈다고 판단하지 않습니다. 학생이 직접 할 수 있는 것과 확인할 부분을 나누는 자료로 사용하세요. 밀린 분량을 한꺼번에 만회하도록 요구하지 않고 필요한 보완부터 고릅니다.'),
('과목별 작은 확인 활동을 정하세요','국어는 중심 내용과 근거, 영어는 문장 의미와 어휘, 수학은 실제 배운 단원의 대표 풀이를 살핍니다. 학년만 보고 아직 배우지 않은 단원을 목록에 넣지 않습니다. 오래 막힌 부분은 원래 교재에서 개념을 찾아 질문을 남기세요. 과제 수는 점검 부담과 실제 수업 내용에 맞춰 조정합니다.'),
('생활과 자료 준비를 실행 조건으로 보세요','등교·이동에 맞춰 취침·기상·준비 시간을 함께 정합니다. 교재·유인물·도구를 찾을 수 있는지 확인하세요. 디지털 기기가 과제에 필요한 사용인지 먼저 나누고 방해 알림은 학생과 상의합니다. 모든 학생에게 같은 공부 시간·기상 시각을 요구하지 않고 실제 생활 안에서 가능한 조건을 찾습니다.'),
('개학 첫 주의 질문으로 마무리하세요','꼭 필요한 보완 하나와 첫 주 질문을 정합니다. 준비 자료를 사용할 수 있게 정리하고 학생의 바람과 걱정을 들으세요. 부모는 일정·자료 확보 등 필요한 지원을 맡습니다. 점검을 비교 시험으로 만들기보다 학교 수업과 평소 복습으로 다시 시작할 수 있는 준비로 사용합니다.')],
'지난 수학 대표 문제 두 개와 영어 문장 한 개를 확인할 수 있습니다. 조건 해석이 막혔다면 그 부분만 질문으로 남깁니다. 첫 주 수업에 준비 자료를 가져가 질문하고 최근 수업 복습부터 시작합니다.',
['학교 안내를 확인했다.','실제로 배운 과제를 골랐다.','표본의 한계를 기억했다.','생활·자료를 준비했다.','첫 주 질문을 정했다.'],
[['방학 내용을 전부 테스트해야 하나요?','최근 과제의 작은 표본으로 시작할 수 있습니다. 필요한 범위를 넓히되 한 번의 결과로 전체 수준을 단정하지 않습니다.'],['밀린 공부를 개학 전에 모두 끝내야 하나요?','필수 과제와 준비를 먼저 확인하세요. 보완은 필요한 부분부터 나누고 첫 주 질문과 연결할 수 있습니다.']],['parents'],'초등공부습관')

add(20,'중고등전환과제연결','중학교에서 고등학교로, 공부 방식의 연결을 준비하는 세 가지 자료','학기·방학','중등·고등·학부모',
'중고등 전환기에 최근 풀이·읽기·학교 안내 자료를 모아 기초 연결과 새 과제의 요구를 확인합니다.',[
('새 학교 안내와 현재 자료를 함께 보세요','선행 진도만으로 준비를 설명하기 어렵습니다. 교재·과제·생활·평가 안내와 현재 독립 수행을 함께 확인하세요. 입학 시기에 따라 안내가 다를 수 있어 오래된 제도 설명을 그대로 적용하지 않습니다. 모든 지문과 과제가 똑같이 어려워진다고 단정하기보다 실제 요구를 읽습니다.'),
('수학은 필요한 연결 개념을 찾으세요','최근 풀이에서 식의 의미·계산·조건 설명을 봅니다. 새 교재의 안내에 필요한 이전 개념이 무엇인지 확인하고 불확실한 부분을 보완하세요. 어려운 문제의 진도보다 기본 개념을 다른 상황에 적용하는 활동부터 시작할 수 있습니다. 답을 기억한 것과 바뀐 조건의 관계를 파악한 것을 나눕니다.'),
('읽기 뒤 근거와 의미를 남기세요','국어·영어의 짧은 글에서 문단 역할·주장 근거·문장 의미를 설명합니다. 길이를 늘리기 전 어디에서 연결이 끊기는지 확인하세요. 영어는 어휘와 구조, 국어는 작품·지문의 근거와 선택지 범위를 살핍니다. 학교 과제의 요약·쓰기 형식이 있으면 그 요구와 비교해 연습할 수 있습니다.'),
('과제 관리 책임도 연결하세요','마감 확인·자료 준비·질문 기록 중 학생이 맡을 일을 정합니다. 부모는 자료와 실행 조건을 돕습니다. 자기주도 학습은 도움을 끊는 뜻이 아니며 질문과 피드백 반영도 필요합니다. 특정 진학 결과를 보장하는 것이 아니라 새 요구에 대응할 자료와 습관을 마련하는 데 초점을 둡니다.')],
'최근 수학 풀이, 국어·영어 읽기 기록, 새 학교 안내를 모읍니다. 식 선택 이유와 읽기 근거를 확인하고 남은 질문 두 개와 첫 과제 마감을 학생이 직접 적습니다. 필요한 도움을 함께 정할 수 있습니다.',
['입학 시기 안내를 확인했다.','현재 수행 자료를 모았다.','연결 기초를 골랐다.','읽기 근거를 확인했다.','학생의 관리 단계를 정했다.'],
[['선행을 많이 해야 하나요?','실제 학교 안내와 현재 기초·수행을 먼저 보세요. 필요한 개념을 보완하고 새 요구에 적용하며 진도를 조정할 수 있습니다.'],['성적 제도는 늘 같나요?','학교급·학년·과목·입학 시기의 안내를 확인해야 합니다. 이 글의 학습 준비를 제도·등급 산출 설명으로 대신 사용하지 않습니다.']],['school'],'고등공부계획')
